import styled from '@emotion/styled';
import {
  PERFORMANCE_CHART_SECTION_BODY_HEIGHT,
  PERFORMANCE_CHART_SECTION_BODY_PADDING_BOTTOM,
} from 'pages/pillars/ValueCreation/PerformanceTool/constants/chartSectionLayout';

export const StyledLineBarChartsGrid = styled.div({
  display: 'grid',
  gridTemplateColumns: '3fr 1fr',
  flex: 1,
  minHeight: 0,
  alignItems: 'stretch',
});

export const StyledChartContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  minWidth: 0,
  minHeight: 0,
  height: '100%',

  '& > div:first-of-type': {
    flex: 1,
    minHeight: 0,
  },

  '& > * + *': {
    flexShrink: 0,
    marginTop: '8px',
  },
});

export const StyledLegendContainer = styled.div({
  display: 'flex',
  justifyContent: 'center',
  position: 'absolute',
  top: 8,
  left: '75%',
  width: '25%',
  padding: '8px 0',
});

export const StyledChartsWrapper = styled.div({
  display: 'flex',
  flexDirection: 'column',
  flex: 1,
  minHeight: 0,
  width: '100%',
});

export const StyledLineBarChartsContainer = styled.div({
  background: '#ffffff',
  width: '100%',
  border: '1px solid rgba(20, 20, 20, 0.16)',
  overflow: 'hidden',
  paddingBottom: '1rem',
});

export const StyledBodyContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  height: PERFORMANCE_CHART_SECTION_BODY_HEIGHT,
  boxSizing: 'border-box',
  paddingBottom: PERFORMANCE_CHART_SECTION_BODY_PADDING_BOTTOM,
  position: 'relative',
});
